from pathlib import Path
import json
ROOT=Path(__file__).resolve().parent.parent
OUT=ROOT/'outputs'/'ten-toes-down-panorama'
data={'games':json.loads((OUT/'game-corpus.json').read_text(encoding='utf8'))['games'],'evidence':json.loads((OUT/'evidence-ledger.json').read_text(encoding='utf8')),'rules':json.loads((OUT/'routing-rules.json').read_text(encoding='utf8')),'pages':json.loads((OUT/'page-index.json').read_text(encoding='utf8'))}
data['credits']=json.loads((ROOT/'work'/'panorama'/'frontmatter.json').read_text(encoding='utf8'))['attribution']
template=r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>The Panorama - The Tellings Cut</title><style>
:root{color-scheme:light;--ink:#272527;--wine:#782a3b;--paper:#fffdf8;--line:#d6cbbf}*{box-sizing:border-box}body{margin:0;background:#eee7db;color:var(--ink);font:17px/1.6 Georgia,serif}main{max-width:1200px;margin:auto;padding:30px 24px 80px}header{border-top:7px solid var(--wine);border-bottom:1px solid var(--wine);padding:18px 0 28px}h1{font-size:clamp(32px,5vw,62px);line-height:1.08;max-width:960px;margin:12px 0 20px}h2{line-height:1.2;font-size:28px}h3{line-height:1.3}.eyebrow,.meta,button,label,summary,.toolbar{font-family:Arial,sans-serif}.eyebrow{letter-spacing:.1em;font-weight:bold;color:var(--wine);font-size:13px}.intro{max-width:800px;font-size:20px}.panel,.card{background:var(--paper);border:1px solid var(--line);border-radius:4px;padding:22px;margin:20px 0}details>summary{cursor:pointer;font-weight:bold;color:var(--wine)}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:18px}.checks{display:flex;flex-wrap:wrap;gap:10px 22px;margin:15px 0}.checks label{font-size:15px}.field label{display:block;font-size:14px;font-weight:bold;margin-bottom:5px}select,input[type=search]{width:100%;font-size:17px;background:white;color:var(--ink);border:1px solid #817269;padding:10px;border-radius:3px}input[type=checkbox]{width:18px;height:18px;vertical-align:middle;margin-right:5px}button{background:var(--wine);color:white;border:2px solid var(--wine);border-radius:4px;padding:10px 15px;font-size:15px;cursor:pointer;line-height:1.3;margin:5px 8px 5px 0}button.secondary{background:white;color:var(--wine)}button:disabled{opacity:.45;cursor:default}button:focus-visible,a:focus-visible,summary:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid #2666a2;outline-offset:3px}a{color:var(--wine);overflow-wrap:anywhere}.small{font-size:14px}.meta{font-size:13px;color:#63564f}.caseTitle{font-style:italic;font-size:21px}.pill{display:inline-block;font:12px Arial,sans-serif;padding:4px 7px;border:1px solid var(--line);margin:2px}.card details{margin-top:14px}.scene{padding-top:14px}.facts dt{font-weight:bold;margin-top:12px;color:var(--wine)}.facts dd{margin:3px 0 0}.scene{border-left:3px solid var(--line);padding-left:17px}.scene p{margin:0 0 9px}#results{display:grid;grid-template-columns:1fr;gap:15px}#results .card{margin:0}.toolbar{display:flex;justify-content:space-between;gap:15px;align-items:center;flex-wrap:wrap}.notice{padding:12px 16px;background:#f6ead6;border-left:4px solid var(--wine)}.status{min-height:1.5em}.route-result:empty{display:none}.rule h3{font-size:20px}.rule p{max-width:900px}.indexrows{columns:2;column-gap:35px}.indexrows li{break-inside:avoid}.pagination{padding:20px 0}.muted{color:#6b5f56}@media(max-width:650px){main{padding:16px 12px 50px}.panel,.card{padding:17px}.indexrows{columns:1}}@media print{body{background:white}main{max-width:none}.no-print{display:none!important}.card{break-inside:avoid}details{display:block}button{display:none}header{padding:0}a{color:black}#results{display:block}}
</style></head><body><main>
<header><div class="eyebrow">TEN TOES DOWN / THE TELLINGS CUT / 240 REAL GAMES</div><h1>The Panorama of Games for Lillian</h1><p class="intro">“Nigga, who put cocaine on the fucking instruction manual?”</p><p>Six rooms. Two hundred and forty games. Aiden has lost control of the party. You still have control of the evening.</p><p class="small">Original ChatGPT prose under Nolan’s creative direction. The Tellings Cut 2.0, 20 September 2026. Adult fiction: reclaimed in-group language, profanity, cocaine references and sexual innuendo. This file works offline; source links open only when you choose them.</p></header>
<section class="panel"><h2>Find something you actually want to play</h2><p>Start with a genre below. Each card puts <strong>why it sounds fun, what you do, the main catch and a first try</strong> up front. Open the longer notes or Aiden’s scene only when you want them.</p><p>The games range from plausible starting points to clearly marked detours. Read the catch on the exact edition. A game that waits for choices can still have difficult menus, heavy reading or tense decisions.</p><p><strong>Every “no” is free.</strong> The ridiculous system never overrides a real preference. You can browse the index, open a page, or close the book.</p><p><a href="Panorama-Complete-Omnibus.pdf">Read the complete PDF</a> · <a href="Ten-Toes-Down-Panorama.epub">Open the reflowable EPUB</a> · <a href="game-index.csv">Get the printable spreadsheet index</a></p></section>
<section class="panel no-print"><h2>Choose a kind of game</h2><div class="field"><label for="shelf">Genre / section</label><select id="shelf"><option value="0">All 240 games</option><option value="1">1. Mysteries and adventures</option><option value="2">2. Strategy, cards and RPGs</option><option value="3">3. Exploration and places to wander</option><option value="4">4. Puzzles and building</option><option value="5">5. Characters and rich stories</option><option value="6">6. Co-op and sharing a game</option></select></div><div class="field"><label for="search">Search titles, stories, catches and Aiden’s reasons</label><input id="search" type="search" placeholder="Try mystery, ghosts, painting, co-op…"></div><p class="small">The first three filters require an explicit developer declaration in the inspected source record. Missing evidence is excluded. These declarations are not a full playthrough guarantee. Mouse-only can still require dragging, and camera comfort does not mean a fixed camera. Holds and menu complexity still need your own check.</p><div class="checks"><label><input id="untimed" type="checkbox">Declared playable without timed input</label><label><input id="camera" type="checkbox">Declared camera comfort</label><label><input id="mouse" type="checkbox">Declared mouse-only option</label></div><p class="small">The filters below are editorial screening tags. Native co-op depends on the edition; sharing a single-player game does not count.</p><div class="checks"><label><input id="waits" type="checkbox">Usually waits for choices</label><label><input id="coop" type="checkbox">Cards marked native co-op</label><label><input id="memory" type="checkbox">Light or moderate tracking</label><label><input id="promising" type="checkbox">Promising starting points</label></div><button id="clear" class="secondary">Clear filters</button><div class="toolbar"><p id="count" aria-live="polite"></p><div class="field"><label for="sort">Order</label><select id="sort"><option value="id">Case number</option><option value="title">Title</option></select></div></div></section>
<div id="results"></div><div class="pagination no-print"><button id="prev">Previous twelve</button><span id="page-label" class="meta"></span><button id="next">Next twelve</button></div>
<details class="panel no-print" id="ceremony"><summary>The unnecessarily elaborate procedure</summary><p>Choose a department, mood and emblem. That gives a case immediately. Dice, snack arithmetic, traits and imaginary stamp tokens are optional. None describes your ability.</p><div class="grid"><div class="field"><label for="dept">Department</label><select id="dept"></select></div><div class="field"><label for="mood">Mood row</label><select id="mood"></select></div><div class="field"><label for="emblem">Emblem column</label><select id="emblem"></select></div></div><p><button id="begin">Open a new case</button><span id="stamps" class="meta"></span></p><details><summary>Unnecessary arithmetic and stationery</summary><p class="small">A session begins with three Stamp Tokens. At most one modification per case: spend a token for +2 OR one reroll of the four dice. Refusing a game never spends a token. Reset the session whenever you choose.</p><div class="field"><label for="trait">Your entirely optional trait</label><select id="trait"></select></div><div class="checks"><label><input type="checkbox" id="drink">A wanted drink is already here (+1)</label><label><input type="checkbox" id="snack">A wanted snack is already here (+1)</label></div><button id="roll">Roll the four ordinary dice</button><button id="bonus" class="secondary">Spend one stamp: +2</button><button id="reroll" class="secondary">Spend one stamp: reroll</button><button id="reset" class="secondary">Reset session</button><p class="status meta" id="dice-state" aria-live="polite"></p><button id="incident" class="secondary">Request an entirely avoidable incident</button><p id="incident-state" aria-live="polite"></p></details><div id="route-status" class="notice status" aria-live="polite">Open a case whenever you want.</div><div id="route-result" class="route-result"></div><p><button id="previous-appeal" class="secondary">One appeal: previous case</button><button id="next-appeal" class="secondary">One appeal: next case</button><button id="veto" class="secondary">No, thank you (free)</button></p><div class="field"><label for="appeal-dept">Or appeal to the same local case in another department</label><select id="appeal-dept"></select></div><button id="department-appeal" class="secondary">Use the one appeal in that department</button></details>
<details class="panel"><summary>Full rules, incidents, traits and credits</summary><div id="full-rules"></div><p>Source novels: <a href="https://github.com/Sodelin/Ten-Toes-Down/tree/main/editions/niggatorial-tellings">the comic six-book edition in Ten Toes Down</a>. This is a separate generated companion; no source novel was revised.</p><p>Original Panorama rules draw inspiration from Fate’s aspects, four signed dice and optional point spending. This is not a Fate rulebook or an endorsement by Evil Hat. Full attribution and source limits appear in the reading files and repository.</p><p><a href="Source-Notes.md">Per-game source notes</a> · <a href="evidence-ledger.json">Evidence ledger</a></p></details>
<footer><p class="meta">The games are real. The ministries are not. No tracking, accounts, saved personal preferences or network requests are built into this file.</p></footer>
</main><script>__ENGINE__</script><script id="catalog-data" type="application/json">__DATA__</script><script>
'use strict';
const D=JSON.parse(document.getElementById('catalog-data').textContent), E=Object.fromEntries(D.evidence.map(e=>[e.id,e])), G=Object.fromEntries(D.games.map(g=>[g.id,g]));
const el=id=>document.getElementById(id), safe=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const keys=['untimed','camera','mouse','waits','coop','memory','promising'];let page=0,filtered=[],tokens=3,rolled=false,modified=false,dice=0,bonus=0,selection=null,originalSelection=null,appeals=0;
function prefs(){return Object.fromEntries(keys.map(k=>[k,el(k).checked]));}
function options(id,list){el(id).innerHTML=list.map((v,i)=>`<option value="${i+1}">${safe(v)}</option>`).join('');}
options('dept',D.rules.departments.map(v=>v.number+'. '+v.title));options('appeal-dept',D.rules.departments.map(v=>v.number+'. '+v.title));options('mood',D.rules.moods);options('emblem',D.rules.emblems);options('trait',['No trait required',...D.rules.aspects.map(v=>v[0])]);
function card(g,open=false){
 const p=D.pages[g.id],tier={promising:'A place to start',conditional:'Read the catch first',detour:'A more demanding detour'}[g.fit_tier];
 const controls={pointer:'Mouse / pointer',directional:'Direction + buttons',camera:'Movement + camera',mixed:'Mixed controls',text:'Dialogue / text choices'}[g.input]||g.input;
 const pace={waits:'Usually waits for choices',real_time:'Action continues while you think',mixed:'Some real-time demands',unknown:'Timing needs checking'}[g.pace];
 const company={yes:'Native co-op in this edition',no:'Single-player; a friend can share decisions',unknown:'Co-op details need checking'}[g.native_coop];
 return `<article class="card" id="case-${g.id}${open?'-route':''}"><div class="meta">${safe(g.id)} / VOLUME ${p.volume}, PAGE ${p.page} / ${safe(tier)}</div><h2>${safe(g.title)}</h2><p class="quick-pitch"><strong>${safe(g.quick_pitch)}</strong></p><dl class="facts"><dt>What you do</dt><dd>${safe(g.what_you_do)}</dd><dt>Main catch</dt><dd>${safe(g.watch_for)}</dd><dt>Try this first</dt><dd>${safe(g.first)}</dd></dl><p class="meta">${safe(controls)} · ${safe(pace)} · ${safe(company)}</p><p class="meta">Edition considered: ${safe(g.edition_target)}</p><details><summary>More about the appeal and the full catch</summary><dl class="facts"><dt>Why it might click</dt><dd>${safe(g.pleasure)}</dd><dt>The full catch</dt><dd>${safe(g.burden)}</dd></dl></details><details class="comedy"><summary>Aiden after hours: ${safe(g.case_title)}</summary><div class="scene">${g.scene.map(p=>'<p>'+safe(p)+'</p>').join('')}<p><strong>Aiden’s verdict.</strong> ${safe(g.ruling)}</p></div></details><details><summary>Sources and the PDF page</summary><p class="small">${safe(g.source_note)}</p><p class="small">Developer declarations imported from exact matching record: ${safe(E[g.id].developer_declarations.join('; ')||'none; unknown is not a negative finding')}.</p><ul>${g.source_urls.map((u,i)=>`<li><a href="${safe(u)}" rel="noreferrer" target="_blank">Source ${i+1}: ${safe(u)}</a></li>`).join('')}</ul><p><a href="Panorama-Volume-${String(p.volume).padStart(2,'0')}.pdf#page=${p.page}">Read this case in Volume ${p.volume}</a></p></details></article>`;
}
function showList(){const q=el('search').value.trim().toLocaleLowerCase(),pr=prefs();filtered=D.games.filter(g=>(!Number(el('shelf').value)||D.pages[g.id].volume===Number(el('shelf').value))&&Panorama.eligible(g,E[g.id],pr)&&(!q||[g.title,g.quick_pitch,g.what_you_do,g.watch_for,g.case_title,g.edition_target,g.pleasure,g.burden,g.first,g.ruling,...g.scene,...g.tone].join(' ').toLocaleLowerCase().includes(q)));if(el('sort').value==='title')filtered.sort((a,b)=>a.title.localeCompare(b.title));const pages=Math.max(1,Math.ceil(filtered.length/12));page=Math.min(page,pages-1);el('count').textContent=`${filtered.length} of 240 cases match. A match is a reading suggestion, not a guarantee.`;el('results').innerHTML=filtered.slice(page*12,page*12+12).map(g=>card(g)).join('')||'<p class="notice">No case has all this recorded evidence. You can change a filter or keep the requirement; the Ministry cannot waive it for you.</p>';el('page-label').textContent=`Page ${page+1} of ${pages}`;el('prev').disabled=page===0;el('next').disabled=page>=pages-1;showRoute();}
function updateButtons(){el('stamps').textContent=`${tokens} imaginary stamps remaining`;el('roll').disabled=!selection||rolled||appeals>0;el('bonus').disabled=!selection||modified||tokens===0||appeals>0;el('reroll').disabled=!selection||!rolled||modified||tokens===0||appeals>0;el('previous-appeal').disabled=el('next-appeal').disabled=!selection||appeals>0;el('veto').disabled=!selection;el('department-appeal').disabled=!selection||appeals>0||+el('appeal-dept').value===selection.department;}
function calculate(){selection=Panorama.route(+el('dept').value,+el('mood').value,+el('emblem').value,dice,Number(el('drink').checked)+Number(el('snack').checked),bonus);originalSelection=selection;appeals=0;showRoute();}
function showRoute(){updateButtons();if(!selection){el('route-result').innerHTML='';return;}const g=G[selection.id],allowed=Panorama.eligible(g,E[g.id],prefs())&&(!Number(el('shelf').value)||D.pages[g.id].volume===Number(el('shelf').value));el('route-status').textContent=`Base ${selection.base}; dice ${dice}; refreshments ${selection.snack}; stamp bonus ${bonus}. ${appeals?'One appeal used. ':''}Case ${selection.id}. ${allowed?'Read the catch and decide freely.':'Outside your current filters. This is not a recommendation; the route cannot override your requirements.'}`;el('route-result').innerHTML=allowed?card(g,true):`<p>${safe(g.title)} is excluded by your current filters. A free refusal is sufficient paperwork.</p>`;if(appeals&&originalSelection){const original=G[originalSelection.id];el('route-result').innerHTML+=`<details class="panel"><summary>The original candidate: ${safe(original.title)}</summary>${(Panorama.eligible(original,E[original.id],prefs())&&(!Number(el('shelf').value)||D.pages[original.id].volume===Number(el('shelf').value)))?card(original,true):'<p>The original candidate is outside your current filters.</p>'}</details>`;}}
function rollDice(){const ds=Array.from({length:4},()=>1+Math.floor(Math.random()*6));dice=Panorama.fourDice(ds);rolled=true;el('dice-state').textContent=`Dice: ${ds.join(', ')}. Signed total: ${dice}. This changes a shelf address, not your score.`;calculate();}
el('begin').onclick=()=>{rolled=false;modified=false;dice=0;bonus=0;el('dice-state').textContent='No dice needed. Your base case is ready.';calculate();};
el('roll').onclick=()=>{if(selection&&!rolled&&appeals===0)rollDice();};
el('bonus').onclick=()=>{if(selection&&!modified&&tokens&&appeals===0){tokens--;modified=true;bonus=2;calculate();}};
el('reroll').onclick=()=>{if(selection&&rolled&&!modified&&tokens&&appeals===0){tokens--;modified=true;rollDice();}};
el('reset').onclick=()=>{tokens=3;selection=null;dice=0;bonus=0;modified=false;rolled=false;appeals=0;el('route-status').textContent='A new browsing session. Three stamps. All refusals still free.';el('dice-state').textContent='';showRoute();};
el('veto').onclick=()=>{selection=null;el('route-status').textContent='Case declined. No additional stamps spent. Pick another case, use the direct index or stop here.';showRoute();};
function appeal(direction){if(selection&&appeals===0){selection=Panorama.appeal(selection,direction,appeals);appeals=1;showRoute();}}el('previous-appeal').onclick=()=>appeal(-1);el('next-appeal').onclick=()=>appeal(1);el('appeal-dept').onchange=updateButtons;el('department-appeal').onclick=()=>{if(selection&&appeals===0&&+el('appeal-dept').value!==selection.department){selection=Panorama.appealDepartment(selection,+el('appeal-dept').value,appeals);appeals=1;showRoute();}};
['dept','mood','emblem','drink','snack'].forEach(id=>el(id).onchange=()=>{if(selection){selection=null;el('route-status').textContent='Route inputs changed. Open a new case when ready.';showRoute();}});
el('incident').onclick=()=>{const x=D.rules.incidents[Math.floor(Math.random()*D.rules.incidents.length)];el('incident-state').textContent=x[0]+'. '+x[1]+' The incident is now closed; choose freely.';};
keys.forEach(id=>el(id).onchange=()=>{page=0;showList();});el('shelf').onchange=()=>{page=0;showList();};el('search').oninput=()=>{page=0;showList();};el('sort').onchange=()=>{page=0;showList();};el('clear').onclick=()=>{keys.forEach(id=>el(id).checked=false);el('search').value='';el('shelf').value='0';page=0;showList();};el('prev').onclick=()=>{if(page>0){page--;showList();el('results').scrollIntoView({block:'start'});}};el('next').onclick=()=>{if((page+1)*12<filtered.length){page++;showList();el('results').scrollIntoView({block:'start'});}};
el('full-rules').innerHTML=D.rules.rules.map(([t,ps])=>`<section class="rule"><h3>${safe(t)}</h3>${ps.map(p=>'<p>'+safe(p)+'</p>').join('')}</section>`).join('')+'<h3>Traits</h3><ul>'+D.rules.aspects.map(([t,p])=>'<li><strong>'+safe(t)+': </strong>'+safe(p)+'</li>').join('')+'</ul><h3>Incidents</h3><ul>'+D.rules.incidents.map(([t,p])=>'<li><strong>'+safe(t)+': </strong>'+safe(p)+'</li>').join('')+'</ul>';showList();
el('full-rules').innerHTML+='<h3>Attribution</h3>'+D.credits.map(p=>'<p>'+safe(p)+'</p>').join('');
</script></body></html>'''
content=template.replace('__ENGINE__',(ROOT/'work'/'panorama-finder.js').read_text(encoding='utf8')).replace('__DATA__',json.dumps(data,ensure_ascii=False).replace('</','<\\/'))
(OUT/'Start-Here.html').write_text(content,encoding='utf8')
print('Offline finder written: '+str(len(content))+' characters; 240 cases inline.')
